package org.rabochaya.projects;
import android.graphics.*;import java.io.*;import java.util.*;
/** Explicit PNG/JPEG pair, read only; bounded regional decode instead of a whole-image bitmap. */
public final class OziRaster implements Closeable,RasterMapImport.Source {
 public static final long MAX_IMAGE=512L*1024*1024;public final OziCalibration calibration;private final BitmapRegionDecoder decoder;private final LinkedHashMap<Long,Bitmap> tiles=new LinkedHashMap<>(16,.75f,true);private long bytes;private boolean closed;
 public OziRaster(File map,File image,String selectedName)throws IOException{
  if(!map.isFile()||map.length()>OziCalibration.MAX_BYTES||!image.isFile()||image.length()>MAX_IMAGE)throw new IOException("Ozi: предел .map 128 КиБ, изображения 512 МиБ");
  byte[] signature=new byte[8];try(DataInputStream in=new DataInputStream(new FileInputStream(image))){in.readFully(signature);}boolean png=Arrays.equals(signature,new byte[]{(byte)137,80,78,71,13,10,26,10}),jpeg=(signature[0]&255)==255&&(signature[1]&255)==216&&(signature[2]&255)==255;if(!png&&!jpeg)throw new IOException("Ozi: поддержаны только PNG/JPEG");
  BitmapRegionDecoder opened=BitmapRegionDecoder.newInstance(image.getPath(),false);if(opened==null)throw new IOException("Ozi: изображение не декодировано");try{int w=opened.getWidth(),h=opened.getHeight();if(w<1||h<1||w>20000||h>20000||(long)w*h>100000000)throw new IOException("Ozi: предел 20 000 по стороне / 100 млн пикселей");try(InputStream in=new FileInputStream(map)){calibration=OziCalibration.read(in,selectedName,w,h);}decoder=opened;}catch(IOException|RuntimeException e){opened.recycle();if(e instanceof IOException)throw (IOException)e;throw new IOException("Ozi: ошибка изображения/привязки",e);}
 }
 public GeoRasterTransform transform(){return calibration.transform;}
 public synchronized int color(double lon,double lat)throws IOException{if(closed)throw new IOException("Ozi reader закрыт");long cell=transform().cell(lon,lat);if(cell<0)return 0;int x=(int)cell,y=(int)(cell>>>32),tx=x/256,ty=y/256;long key=(long)ty<<32|tx;Bitmap tile=tiles.get(key);if(tile==null){BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.ARGB_8888;options.inScaled=false;int left=tx*256,top=ty*256;try{tile=decoder.decodeRegion(new Rect(left,top,Math.min(left+256,transform().width),Math.min(top+256,transform().height)),options);}catch(RuntimeException e){throw new IOException("Ozi: ошибка чтения региона",e);}if(tile==null)throw new IOException("Ozi: пустой регион изображения");long size=tile.getByteCount();while(!tiles.isEmpty()&&(tiles.size()>=64||bytes+size>16L*1024*1024)){Iterator<Map.Entry<Long,Bitmap>> it=tiles.entrySet().iterator();Bitmap old=it.next().getValue();it.remove();bytes-=old.getByteCount();old.recycle();}tiles.put(key,tile);bytes+=size;}return tile.getPixel(x%256,y%256);}
 public synchronized void close(){if(closed)return;closed=true;for(Bitmap tile:tiles.values())tile.recycle();tiles.clear();bytes=0;decoder.recycle();}
}
